using System;
using System.IO;
using System.Collections.Generic;

class MikroInputTests {
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);}
 static byte[] Pad(int id,int kind,int value){var r=new byte[64];r[0]=2;r[1]=(byte)id;r[2]=(byte)(kind|(value>>8));r[3]=(byte)value;return r;}
 static int Main(string[] args){
  var input=new MikroInput();var on=new List<int>();var velocity=new List<int>();var active=new HashSet<int>();int off=0,peak=0;var transport=new List<MikroTransport>();
  input.Note+=(n,v,down)=>{if(down){Check(active.Add(n),"duplicate note");on.Add(n);velocity.Add(v);peak=Math.Max(peak,active.Count);}else{Check(active.Remove(n),"unmatched release");off++;}};
  input.Transport+=transport.Add;
  foreach(string line in File.ReadLines(args[0])){
   var r=new byte[line.Length/2];for(int i=0;i<r.Length;i++)r[i]=Convert.ToByte(line.Substring(i*2,2),16);input.Feed(r);
  }
  Check(on.Count==37 && off==37 && active.Count==0 && peak==3,"captured note lifecycle");
  for(int i=0;i<16;i++)Check(on[i]==36+i,"physical pad order");
  Check(velocity[16]==50 && velocity[17]==90 && velocity[18]==127,"captured velocity");
  Check(transport.Count==6,"transport press count");
  for(int i=0;i<6;i++)Check(transport[i]==new[]{MikroTransport.Play,MikroTransport.Stop,MikroTransport.Record}[i%3],"transport order");
  input.Feed(Pad(12,0x10,1600));input.Feed(Pad(12,0x10,1600));input.Feed(Pad(12,0x40,2000));
  Check(active.Count==1,"suppress repeats and pressure");input.Reset();Check(active.Count==0,"release on pause/reset");
  input.Feed(null);input.Feed(new byte[3]);input.Feed(Pad(255,0x10,1000));Check(active.Count==0,"malformed pad ignored");
  var pair=new byte[128];Array.Copy(Pad(0,0x10,2000),pair,64);Array.Copy(Pad(0,0x30,0),0,pair,64,64);input.Feed(pair);Check(active.Count==0,"both report blocks decoded");
  input.Feed(Pad(12,0x10,1600));input.BaseNote=52;input.Feed(Pad(12,0x30,0));Check(active.Count==0,"bank change releases original note");
  input.Feed(Pad(12,0x10,1600));Check(active.Contains(52),"new bank note");input.BaseNote=36;
  input.Feed(Pad(12,0x30,0));Check(active.Count==0,"return bank does not alter held pitch");
  var pressureInput=new MikroInput();var pressures=new List<string>();int pressureNotes=0;
  pressureInput.Pressure+=(n,v)=>pressures.Add(n+":"+v);pressureInput.Note+=(n,v,d)=>pressureNotes++;
  pressureInput.Feed(Pad(12,0x40,4095));Check(pressures.Count==0,"pressure before strike is ignored");
  pressureInput.Feed(Pad(12,0x10,1600));pressureInput.BaseNote=52;
  foreach(int raw in new[]{1024,4095,0})pressureInput.Feed(Pad(12,0x40,raw));
  Check(string.Join(",",pressures)=="36:32,36:127,36:1"&&pressureNotes==1,"pressure follows held pitch and stays within playable velocity without extra notes");
  pressureInput.Feed(Pad(12,0x30,0));pressureInput.Feed(Pad(12,0x40,4095));Check(pressures.Count==3&&pressureNotes==2,"pressure after release cannot revive a voice");
  foreach(bool sixteen in new[]{false,true}){pressureInput.SelectedNote=36;pressureInput.SetMode(!sixteen,sixteen);pressureInput.Feed(Pad(12,0x10,1600));pressureInput.Feed(Pad(12,0x40,2048));pressureInput.Feed(Pad(12,0x30,0));}
  Check(pressures.Count==3,"Fixed Vel and 16 Vel ignore continuous pressure");
  input.BaseNote=4;input.Feed(Pad(12,0x10,1600));input.BaseNote=0;input.Feed(Pad(8,0x10,1600));
  Check(active.Count==1&&active.Contains(4),"overlapping edge banks share one held voice");input.Feed(Pad(12,0x30,0));Check(active.Contains(4),"overlap stays held until final release");input.Reset();Check(active.Count==0,"reset releases overlapping voice");
  var banks=new List<int>();input.Bank+=banks.Add;var arrows=new byte[64];arrows[0]=1;arrows[2]=1;input.Feed(arrows);input.Feed(arrows);arrows[2]=0;input.Feed(arrows);arrows[2]=2;input.Feed(arrows);
  Check(banks.Count==2&&banks[0]==-1&&banks[1]==1,"arrow edges and duplicate suppression");
  input.Reset();transport.Clear();var tap=new byte[64];tap[0]=1;tap[3]=16;
  input.Feed(tap);input.Feed(tap);tap[3]=0;input.Feed(tap);
  tap[4]=2;input.Feed(tap);tap[3]=16;input.Feed(tap);input.Feed(tap);
  tap[4]=0;input.Feed(tap);tap[3]=0;input.Feed(tap);
  Check(transport.Count==2 && transport[0]==MikroTransport.TapTempo && transport[1]==MikroTransport.Metronome,"tap modifier snapshot, release and held suppression");
  input.Reset();transport.Clear();var grids=new List<bool>();input.Grid+=grids.Add;var follow=new byte[64];follow[0]=1;follow[3]=32;input.Feed(follow);input.Feed(follow);
  follow[3]=0;input.Feed(follow);follow[4]=2;input.Feed(follow);follow[3]=32;input.Feed(follow);input.Feed(follow);
  Check(transport.Count==1&&transport[0]==MikroTransport.Follow&&string.Join(",",grids)=="True","shifted Follow enters held Grid without toggling Follow");
  follow[4]=0;input.Feed(follow);input.Feed(follow);
  Check(string.Join(",",grids)=="True,False"&&transport.Count==1,"releasing Shift exits Grid without triggering held Follow");
  follow[4]=2;input.Feed(follow);follow[3]=0;input.Feed(follow);
  Check(string.Join(",",grids)=="True,False,True,False","releasing Follow also exits Grid");
  follow[3]=32;input.Feed(follow);input.Reset();Check(string.Join(",",grids)=="True,False,True,False,True,False","reset releases held Grid");
  var modes=new MikroInput();var events=new List<string>();int chosen=-1;
  modes.Note+=(n,v,d)=>events.Add(n+":"+v+":"+d);modes.Selected+=n=>chosen=n;
  modes.FixedValue=99;modes.SetMode(true,false);modes.Feed(Pad(12,0x10,32));
  Check(chosen==36&&events[0]=="36:99:True","fixed velocity and selected note");
  modes.SetMode(false,true);Check(events[1]=="36:0:False","mode change releases notes");events.Clear();
  modes.Feed(Pad(12,0x10,4095));modes.Feed(Pad(3,0x10,32));
  Check(events.Count==3&&events[0]=="36:1:True"&&events[1]=="36:0:False"&&events[2]=="36:127:True","16 velocity retriggers same pitch with endpoint velocities");
  modes.Feed(Pad(12,0x30,0));Check(events.Count==3,"first overlapping release does not stop remaining pad");
  modes.BaseNote=52;modes.Feed(Pad(3,0x30,0));Check(events[3]=="36:0:False"&&chosen==36,"last release uses original note and 16 vel preserves selection");
  modes.SetMode(false,false);modes.Feed(Pad(12,0x10,1600));Check(chosen==52,"normal mode selects new bank note");modes.Reset();
  for(int i=1;i<16;i++)Check(MikroInput.StepVelocity(i)>MikroInput.StepVelocity(i-1),"16 distinct increasing velocities");
  var controls=new List<MikroTransport>();modes.Transport+=controls.Add;var extra=new byte[64];extra[0]=1;extra[5]=0x60;extra[4]=4;modes.Feed(extra);modes.Feed(extra);
  Check(controls.Count==3&&controls.Contains(MikroTransport.Mute)&&controls.Contains(MikroTransport.Solo)&&controls.Contains(MikroTransport.FixedVelocity),"five-byte buttons decoded once");
  extra[4]=2;extra[5]=0;modes.Feed(extra);extra[4]=6;modes.Feed(extra);Check(controls[3]==MikroTransport.SixteenVelocity,"shift fixed selects 16 velocity");
  var keyboard=new MikroInput();var keyboardEvents=new List<string>();keyboard.Note+=(n,v,d)=>keyboardEvents.Add(n+":"+d);
  keyboard.KeyboardNotes=new[]{36,38,40,41,43,45,47,48,50,52,53,55,57,59,60,62};
  keyboard.Feed(Pad(12,0x10,1600));keyboard.KeyboardNotes[0]=38;keyboard.Feed(Pad(12,0x30,0));
  Check(keyboardEvents[0]=="36:True"&&keyboardEvents[1]=="36:False","keyboard remapping preserves held pitch release");
  keyboard.Feed(Pad(13,0x10,1600));Check(keyboardEvents[2]=="38:True","keyboard consecutive pad follows scale");keyboard.Reset();
  keyboard.KeyboardNotes[0]=-1;int before=keyboardEvents.Count;keyboard.Feed(Pad(12,0x10,1600));Check(keyboardEvents.Count==before,"out of range keyboard pad inert");
  var turns=new List<int>();keyboard.Encoder+=turns.Add;var dial=new byte[64];dial[0]=1;dial[7]=15;keyboard.Feed(dial);dial[7]=0;keyboard.Feed(dial);keyboard.Feed(dial);dial[7]=15;keyboard.Feed(dial);dial[7]=7;keyboard.Feed(dial);
  Check(turns.Count==2&&turns[0]==1&&turns[1]==-1,"encoder modulo wrap, duplicates and half-turn ambiguity");
  var modeButtons=new List<MikroTransport>();keyboard.Transport+=modeButtons.Add;dial[4]=8;keyboard.Feed(dial);dial[4]=16;keyboard.Feed(dial);dial[4]=0;dial[5]=128;keyboard.Feed(dial);keyboard.Feed(dial);
  Check(modeButtons.Count==3&&modeButtons[0]==MikroTransport.PadMode&&modeButtons[1]==MikroTransport.KeyboardMode&&modeButtons[2]==MikroTransport.ScaleToggle,"pad keyboard and encoder press edges");
  keyboard.Reset();turns.Clear();var rootTurns=new List<int>();keyboard.RootEncoder+=rootTurns.Add;
  dial=new byte[64];dial[0]=1;keyboard.Feed(dial);dial[4]=2;dial[7]=1;keyboard.Feed(dial);dial[7]=0;keyboard.Feed(dial);
  Check(turns.Count==0&&rootTurns.Count==2&&rootTurns[0]==1&&rootTurns[1]==-1,"shift encoder changes only root");
  var resets=new List<int>();keyboard.Bank+=resets.Add;keyboard.Reset();dial=new byte[64];dial[0]=1;dial[2]=3;keyboard.Feed(dial);keyboard.Feed(dial);dial[2]=1;keyboard.Feed(dial);dial[2]=3;keyboard.Feed(dial);
  Check(resets.Count==1&&resets[0]==0,"arrow chord resets once until both released");dial[2]=0;keyboard.Feed(dial);dial[2]=2;keyboard.Feed(dial);dial[2]=3;keyboard.Feed(dial);
  Check(resets.Count==3&&resets[1]==1&&resets[2]==0,"staggered arrow chord ends in reset");
  var editing=new MikroInput();var music=new List<string>();var commands=new List<int>();editing.Note+=(n,v,d)=>music.Add(n+":"+d);editing.Edit+=commands.Add;
  editing.Feed(Pad(12,0x10,1600));var shift=new byte[64];shift[0]=1;shift[4]=2;editing.Feed(shift);editing.Feed(Pad(12,0x30,0));
  Check(music.Count==2&&music[1]=="36:False","held musical note releases under Shift");
  editing.Feed(Pad(13,0x10,1600));editing.Feed(Pad(13,0x10,1600));editing.Feed(Pad(13,0x40,1600));
  shift[4]=0;editing.Feed(shift);editing.Feed(Pad(13,0x10,1600));editing.Feed(Pad(13,0x30,0));
  Check(commands.Count==1&&commands[0]==2&&music.Count==2,"shift commands suppress notes and pressure until pad release");
  editing.Feed(Pad(13,0x10,1600));Check(music.Count==3,"normal notes resume after shifted pad released");editing.Reset();
  var selecting=new MikroInput();int musicCount=0,picked=-1;selecting.Note+=(n,v,d)=>musicCount++;selecting.SelectEvent+=n=>picked=n;selecting.SelectOnly=true;
  selecting.Feed(Pad(12,0x10,1600));selecting.Feed(Pad(12,0x10,1600));selecting.SelectOnly=false;selecting.Feed(Pad(12,0x10,1600));selecting.Feed(Pad(12,0x30,0));
  Check(picked==36&&musicCount==0,"Events selection does not play notes and suppresses held pad on exit");
  selecting.SelectOnly=true;int editCommand=0;selecting.Edit+=n=>editCommand=n;shift[4]=2;selecting.Feed(shift);selecting.Feed(Pad(12,0x10,1600));selecting.Feed(Pad(12,0x30,0));
  Check(editCommand==1&&musicCount==0,"Shift editing retains priority inside Events");
  var eventButtons=new List<MikroTransport>();selecting.Transport+=eventButtons.Add;var eventsButton=new byte[64];eventsButton[0]=1;eventsButton[5]=2;selecting.Feed(eventsButton);selecting.Feed(eventsButton);
  Check(eventButtons.Count==1&&eventButtons[0]==MikroTransport.Events,"Events button physical mapping");
  var restartInput=new MikroInput();var restartCommands=new List<MikroTransport>();restartInput.Transport+=restartCommands.Add;var transportReport=new byte[64];transportReport[0]=1;transportReport[3]=4;restartInput.Feed(transportReport);restartInput.Feed(transportReport);transportReport[3]=0;transportReport[4]=2;restartInput.Feed(transportReport);transportReport[3]=4;restartInput.Feed(transportReport);transportReport[3]=8;restartInput.Feed(transportReport);
  Check(restartCommands.Count==3&&restartCommands[0]==MikroTransport.Restart&&restartCommands[1]==MikroTransport.Loop&&restartCommands[2]==MikroTransport.Erase,"Restart Loop and Erase button mapping");
  var stepInput=new MikroInput();stepInput.StepOnly=true;stepInput.KeyboardNotes=new[]{60,62,64,65,67,69,71,72,74,76,77,79,81,83,84,86};
  var stepCommands=new List<int>();var previewMusic=new List<string>();var previewControls=new List<MikroTransport>();var previewEdits=new List<int>();var previewTurns=new List<int>();var previewBanks=new List<int>();int previewPitch=-1;
  stepInput.StepPad+=stepCommands.Add;stepInput.Note+=(n,v,d)=>previewMusic.Add(n+":"+d);stepInput.Selected+=n=>previewPitch=n;
  var previewGrids=new List<bool>();stepInput.Grid+=previewGrids.Add;
  stepInput.Transport+=previewControls.Add;stepInput.Edit+=previewEdits.Add;stepInput.Encoder+=previewTurns.Add;stepInput.RootEncoder+=previewTurns.Add;stepInput.Bank+=previewBanks.Add;
  var previewReport=new byte[64];previewReport[0]=1;stepInput.Feed(previewReport);previewReport[5]=16;stepInput.Feed(previewReport);
  stepInput.Feed(Pad(13,0x10,1600));stepInput.Feed(Pad(13,0x10,1600));
  Check(previewPitch==37&&previewMusic.Count==1&&previewMusic[0]=="37:True"&&stepCommands.Count==0&&previewEdits.Count==0,"Select Step auditions chromatic pad bank and selects pitch instead of editing");
  for(int i=1;i<=5;i++)previewReport[i]=255;previewReport[2]&=191;previewReport[7]=5;stepInput.Feed(previewReport);
  Check(previewControls.Count==1&&previewControls[0]==MikroTransport.ScaleToggle&&previewTurns.Count==1&&previewBanks.Count==0,"Step preview permits encoder turn and press but blocks other buttons and arrows");
  previewReport[5]=(byte)(previewReport[5]&~16);stepInput.Feed(previewReport);
  Check(previewMusic.Count==2&&previewMusic[1]=="37:False","Select release stops held preview notes");
  stepInput.Feed(previewReport);stepInput.Feed(Pad(13,0x10,1600));stepInput.Feed(Pad(13,0x30,0));
  Check(stepCommands.Count==0&&previewControls.Count==1&&previewBanks.Count==0&&previewGrids.Count==0,"blocked buttons including Grid and audition pad stay consumed until release");
  Array.Clear(previewReport,1,5);stepInput.Feed(previewReport);stepInput.Feed(Pad(13,0x10,1600));stepInput.Feed(Pad(13,0x30,0));
  Check(stepCommands.Count==1&&stepCommands[0]==1,"Step editing resumes after preview pad release");
  previewReport[5]=16;stepInput.Feed(previewReport);stepInput.Feed(Pad(12,0x10,1600));stepInput.Feed(Pad(12,0x30,0));
  Check(previewMusic.Count==4&&previewMusic[2]=="36:True"&&previewMusic[3]=="36:False","preview pad release works before Select release");stepInput.Reset();
  var melodicPreview=new MikroInput();melodicPreview.StepOnly=true;melodicPreview.PreviewNotes=new[]{60,62,64,65,67,69,71,72,74,76,77,79,81,83,84,86};
  var melodicNotes=new List<string>();melodicPreview.Note+=(n,v,d)=>melodicNotes.Add(n+":"+d);
  var melodicHold=new byte[64];melodicHold[0]=1;melodicHold[5]=16;melodicPreview.Feed(melodicHold);melodicPreview.Feed(Pad(14,0x10,1600));
  melodicPreview.PreviewNotes=new[]{72,74,76,77,79,81,83,84,86,88,89,91,93,95,96,98};melodicPreview.Feed(Pad(14,0x30,0));
  Check(string.Join(",",melodicNotes)=="64:True,64:False","melodic preview respects scale and releases original pitch after range changes");
  var stepEdits=new MikroInput();stepEdits.StepOnly=true;int undo=0,notesDuringUndo=0;stepEdits.Edit+=c=>undo=c;stepEdits.Note+=(n,v,d)=>notesDuringUndo++;
  var editShift=new byte[64];editShift[0]=1;editShift[4]=2;stepEdits.Feed(editShift);stepEdits.Feed(Pad(12,0x10,1600));stepEdits.Feed(Pad(12,0x30,0));
  Check(undo==1&&notesDuringUndo==0,"Shift Undo remains available inside Step without auditioning notes");
  var stripInput=new MikroInput();var touches=new List<int>();stripInput.Strip+=touches.Add;var stripReport=new byte[64];stripReport[0]=1;
  foreach(int raw in new[]{1,100,100,200,0,255}){stripReport[10]=(byte)raw;stripInput.Feed(stripReport);}
  Check(string.Join(",",touches)=="1,100,200,0","strip changes release deduplication and invalid raw range");
  var repeatEdges=new List<bool>();stripInput.Repeat+=repeatEdges.Add;stripReport[10]=0;stripReport[3]=2;stripInput.Feed(stripReport);stripInput.Feed(stripReport);
  stripReport[3]=0;stripInput.Feed(stripReport);stripReport[3]=2;stripInput.Feed(stripReport);stripInput.Reset();
  Check(string.Join(",",repeatEdges)=="True,False,True,False","Note Repeat hold release deduplication and reset");
  var patternInput=new MikroInput();patternInput.PatternOnly=true;var launches=new List<int>();int patternNotes=0,patternEdits=0;var patternButtons=new List<MikroTransport>();
  patternInput.PatternPad+=launches.Add;patternInput.Note+=(n,v,d)=>patternNotes++;patternInput.Edit+=c=>patternEdits++;patternInput.Transport+=patternButtons.Add;
  var patternReport=new byte[64];patternReport[0]=1;patternReport[5]=1;patternInput.Feed(patternReport);patternInput.Feed(patternReport);
  patternInput.Feed(Pad(0,0x10,1600));patternInput.Feed(Pad(0,0x10,1600));patternInput.Feed(Pad(0,0x30,0));
  Check(string.Join(",",launches)=="12,28"&&patternNotes==0&&patternEdits==0,"Pattern pads launch and release without notes or Shift edits");
  Check(patternButtons.Count==1&&patternButtons[0]==MikroTransport.Pattern,"Pattern button physical mapping and press deduplication");
  patternReport[4]=2;patternInput.Feed(patternReport);int beforeBlocked=launches.Count;
  patternInput.Feed(Pad(0,0x10,1600));patternReport[4]=0;patternInput.Feed(patternReport);patternInput.Feed(Pad(0,0x10,1600));patternInput.Feed(Pad(0,0x30,0));
  Check(launches.Count==beforeBlocked,"Stop layer upper pads remain inert through Shift release until physical pad release");
  patternReport[4]=2;patternInput.Feed(patternReport);
