  patternInput.ReleaseAll();patternInput.PatternOnly=false;patternInput.Feed(Pad(12,0x10,1600));patternInput.Feed(Pad(12,0x30,0));
  Check(patternNotes==0&&patternEdits==0&&launches[launches.Count-1]==16,"mode exit releases and consumes held launch pad");
