  var selectClipReport=new byte[64];selectClipReport[0]=1;selectClipReport[5]=16;selectingClip.Feed(selectClipReport);
  selectingClip.Feed(Pad(0,0x10,1600));selectClipReport[5]=0;selectingClip.Feed(selectClipReport);selectingClip.Feed(Pad(0,0x10,1600));selectingClip.Feed(Pad(0,0x30,0));
  Check(string.Join(",",clipSelections)=="60","Select pad chooses clip once without launch when Select is released first");
